(function() {
  'use strict';

  const api = window.CardSpoke.utils;
  const emojiMap = {
    todo: '⬜',
    doing: '⏳',
    done: '✅',
    blocked: '⛔'
  };

  function decorateTags() {
    const tagChips = document.querySelectorAll('.tag-chip');
    tagChips.forEach(chip => {
      const tagText = chip.textContent.trim().toLowerCase();
      if (!emojiMap[tagText]) return;

      if (chip.querySelector('.status-emoji-tag')) return;

      const marker = document.createElement('span');
      marker.className = 'status-emoji-tag';
      marker.dataset.status = tagText;
      marker.textContent = emojiMap[tagText];
      chip.appendChild(marker);
    });
  }

  const observer = new MutationObserver(() => setTimeout(decorateTags, 50));
  observer.observe(document.body, { childList: true, subtree: true });
  decorateTags();

  api.showToast('Status Emoji Plugin loaded', 'info');
})();
